<?php
require __DIR__.'/config.php'; require_role(['admin','teacher']);$students=read_json('students');$invoices=read_json('invoices');$payments=read_json('payments');$id=(int)($_GET['student_id']??0);$st=null;foreach($students as $x)if((int)$x['id']===$id)$st=$x;if(!$st)exit('Student not found.');$inv=array_values(array_filter($invoices,fn($x)=>(int)$x['student_id']===$id));$pay=array_values(array_filter($payments,fn($x)=>(int)$x['student_id']===$id));$ti=array_sum(array_column($inv,'amount'));$tp=array_sum(array_column($pay,'amount'));
